-- 딜러 견적서 "품목(라인아이템)" 단위 데이터.
-- dealer_quotes(0014)는 견적서 1건당 합계금액만 담고 있어 품목별/카테고리별
-- 분석이 불가능해서 별도 테이블로 분리한다. dealer_quotes와는 kr_code/order_no로
-- 느슨하게만 연관되며 FK로 강제하지 않는다 — 견적서 헤더 쪽(dealer_quotes)
-- 정합성 작업과 무관하게 품목 데이터를 독립적으로 최신화할 수 있게 하기 위함.
--
-- category/subcategory 분류 기준 (Claude가 견적서 PDF 175건을 직접 파싱해서
-- 2026-09-30에 만든 체계 — products.category/subcategory의 Champion/Edge/Pro
-- 3단계 체계와는 다른 별도 체계입니다):
--   패들 서브카테고리: 프로V / 프로IV / 비전 / 엣지 / 챔피언 / 3S / PowerFX /
--                      기타(엔트리) / 기타(세트) / 기타(C2 CFS)
--   그 외 대분류(공/악세사리/의류/신발)는 subcategory가 없다(null).
--
-- kr_code/order_no가 비어있는 행이 1건 있다 — 원본 파일명이
-- "KR09 2606 견적서(비전 하이페리온).pdf"처럼 하이픈 없이 저장되어 있어
-- 주문번호를 특정하지 못했다(신세계홀세일/09번 딜러 소속인 것은 확실).
--
-- 배송비(Delivery Cost) 행은 제품 판매가 아니므로 제외했고, 동일 주문번호로
-- 여러 번 올라온 수정본은 최신본만 반영했다(KR09-2622, KR10-2618).
-- 대상: 00. 스포츠스쿼드 주식회사 제외, 2026년 견적서만(2025년은 iCloud
-- cloud-only 상태라 이번 세션에서 읽지 못했다).

create table if not exists dealer_quote_items (
  id uuid primary key default gen_random_uuid(),
  kr_code text,
  order_no text,
  quote_date date not null,
  product_name text not null,
  category text not null,
  subcategory text,
  quantity numeric not null,
  unit_price numeric,
  amount numeric not null,
  tax numeric,
  source_file text not null,
  created_at timestamptz not null default now()
);

create index if not exists dealer_quote_items_kr_code_idx on dealer_quote_items (kr_code);
create index if not exists dealer_quote_items_category_idx on dealer_quote_items (category);
create index if not exists dealer_quote_items_quote_date_idx on dealer_quote_items (quote_date);

alter table dealer_quote_items enable row level security;

create policy dealer_quote_items_select on dealer_quote_items
  for select using (auth.role() = 'authenticated');
create policy dealer_quote_items_insert on dealer_quote_items
  for insert with check (can_write());
create policy dealer_quote_items_update on dealer_quote_items
  for update using (can_write()) with check (can_write());
create policy dealer_quote_items_delete on dealer_quote_items
  for delete using (can_write());

-- 품목 데이터 백필 (2026년 1~9월, 175건 견적서 기준, 2026-09-30 스냅샷, 1,211행)
